    "id": "l-b2-7",
    "mode": "listen",
    "level": "B2",
    "theme": "Environnement & Climat",
    "en": "Climatologists emphasize that carbon offsets should never substitute for immediate emissions cuts. Unless industrialized nations implement structural reforms, global temperature thresholds will inevitably be breached.",
    "fr": "Les climatologues soulignent que la compensation carbone ne saurait se substituer à une réduction immédiate des émissions. À moins que les pays industrialisés ne mettent en œuvre des réformes structurelles, les seuils de température mondiaux seront inévitablement franchis.",
    "grammarTitle": "Unless + présent & vocabulaire de khôlle",
